+const pptxgen = require("pptxgenjs");
+const { addPageBadge, addSlideTitle, addSource } = require("./helpers");
+
+const slideConfig = {
+  type: "content",
+  index: 2,
+  title: "Global CO₂ Emissions Grew from 6 Bt in 1950 to Over 35 Bt Today"
+};
+
+function createSlide(pres, theme) {
+  const slide = pres.addSlide();
+  slide.background = { color: theme.bg };
+
+  addSlideTitle(slide, theme, slideConfig.title);
+  addPageBadge(slide, theme, 2);
+
+  // Chart container
+  slide.addShape(pres.ShapeType.roundRect, {
+    x: 0.6,
+    y: 1.2,
+    w: 8.9,
+    h: 3.75,
+    fill: { color: theme.bg },
+    line: { color: theme.accent, width: 1 }
+  });
+
+  // Approximate long-run trajectory (illustrative only; no fabricated data points)
+  // Values used are ONLY the anchor points provided in the brief.
+  const data = [
+    { year: 1750, value: 0.1 },
+    { year: 1950, value: 6 },
+    { year: 1990, value: 20 },
+    { year: 2024, value: 35.5 }
+  ];
+  const x0 = 0.9;
+  const y0 = 4.65;
+  const w = 8.3;
+  const h = 3.0;
+  const maxY = 36;
+
+  // Axes
+  slide.addShape(pres.ShapeType.line, { x: x0, y: y0, w, h: 0, line: { color: theme.secondary, width: 1 } });
+  slide.addShape(pres.ShapeType.line, { x: x0, y: y0 - h, w: 0, h, line: { color: theme.secondary, width: 1 } });
+
+  // Y labels (0, 10, 20, 30, 35+)
+  const yTicks = [0, 10, 20, 30, 35];
+  yTicks.forEach((t) => {
+    const yy = y0 - (t / maxY) * h;
+    slide.addShape(pres.ShapeType.line, {
+      x: x0,
+      y: yy,
+      w: 0.08,
+      h: 0,
+      line: { color: theme.secondary, width: 1 }
+    });
+    slide.addText(String(t), {
+      x: 0.62,
+      y: yy - 0.12,
+      w: 0.25,
+      h: 0.22,
+      fontFace: "Calibri",
+      fontSize: 10,
+      color: theme.secondary,
+      align: "right"
+    });
+  });
+
+  // X labels
+  const xYears = [1750, 1900, 1950, 2000, 2024];
+  xYears.forEach((yr) => {
+    const xx = x0 + ((yr - 1750) / (2024 - 1750)) * w;
+    slide.addShape(pres.ShapeType.line, { x: xx, y: y0, w: 0, h: 0.08, line: { color: theme.secondary, width: 1 } });
+    slide.addText(String(yr), {
+      x: xx - 0.25,
+      y: y0 + 0.08,
+      w: 0.5,
+      h: 0.25,
+      fontFace: "Calibri",
+      fontSize: 10,
+      color: theme.secondary,
+      align: "center"
+    });
+  });
+
+  function pt(year, value) {
+    const xx = x0 + ((year - 1750) / (2024 - 1750)) * w;
+    const yy = y0 - (value / maxY) * h;
+    return { x: xx, y: yy };
+  }
+
+  // Line segments
+  for (let i = 0; i < data.length - 1; i++) {
+    const a = pt(data[i].year, data[i].value);
+    const b = pt(data[i + 1].year, data[i + 1].value);
+    slide.addShape(pres.ShapeType.line, {
+      x: a.x,
+      y: a.y,
+      w: b.x - a.x,
+      h: b.y - a.y,
+      line: { color: theme.primary, width: 3 }
+    });
+  }
+
+  // Anchor dots + labels
+  const anchors = [
+    { year: 1950, value: 6, label: "~6 Bt (1950)" },
+    { year: 1990, value: 20, label: "Over 20 Bt (1990)" },
+    { year: 2024, value: 35.5, label: ">35 Bt (today)" }
+  ];
+  anchors.forEach((a) => {
+    const p = pt(a.year, a.value);
+    slide.addShape(pres.ShapeType.ellipse, {
+      x: p.x - 0.05,
+      y: p.y - 0.05,
+      w: 0.1,
+      h: 0.1,
+      fill: { color: theme.accent },
+      line: { color: theme.accent }
+    });
+    slide.addText(a.label, {
+      x: Math.min(8.6, p.x + 0.12),
+      y: p.y - 0.18,
+      w: 1.8,
+      h: 0.3,
+      fontFace: "Calibri",
+      fontSize: 12,
+      color: theme.primary
+    });
+  });
+
+  // Inflection callouts (text-only; no extra numeric claims)
+  slide.addShape(pres.ShapeType.roundRect, {
+    x: 6.6,
+    y: 1.35,
+    w: 2.85,
+    h: 1.05,
+    fill: { color: theme.light, transparency: 20 },
+    line: { color: theme.light }
+  });
+  slide.addText(
+    "Inflection points:\n• Slow pre‑industrial growth\n• Post‑1950 acceleration\n• Recent slowing, no peak",
+    {
+      x: 6.75,
+      y: 1.45,
+      w: 2.6,
+      h: 0.9,
+      fontFace: "Calibri",
+      fontSize: 12,
+      color: theme.primary
+    }
+  );
+
+  addSource(slide, theme, "Source: Global Carbon Budget 2025 via Our World in Data (fossil fuels & industry).");
+
+  return slide;
+}
+
+if (require.main === module) {
+  const pres = new pptxgen();
+  pres.layout = "LAYOUT_16x9";
+  const theme = {
+    primary: "22223b",
+    secondary: "4a4e69",
+    accent: "9a8c98",
+    light: "c9ada7",
+    bg: "f2e9e4"
+  };
+  createSlide(pres, theme);
+  pres.writeFile({ fileName: "slide-02-preview.pptx" });
+}
+
+module.exports = { createSlide, slideConfig };
+
*** End Patch
